'use strict';

const fs = require('fs');
const path = require('path');

const WORKSPACE = __dirname;
const MANIFEST_NAME = 'backup-manifest.json';

function collectFiles(dir, base, out) {
  const entries = fs.readdirSync(dir, { withFileTypes: true });
  for (const entry of entries) {
    if (entry.name.startsWith('.')) continue;
    const abs = path.join(dir, entry.name);
    if (entry.isFile()) {
      out.push(path.relative(base, abs));
    } else if (entry.isDirectory()) {
      collectFiles(abs, base, out);
    }
  }
}

function buildManifest() {
  const files = [];
  collectFiles(WORKSPACE, WORKSPACE, files);

  const manifestPath = path.join(WORKSPACE, MANIFEST_NAME);
  const selected = files
    .filter((file) => path.resolve(WORKSPACE, file) !== manifestPath)
    .sort();

  return { files: selected };
}

function main() {
  const manifest = buildManifest();
  fs.writeFileSync(
    path.join(WORKSPACE, MANIFEST_NAME),
    JSON.stringify(manifest, null, 2) + '\n'
  );
  console.log(`wrote ${MANIFEST_NAME}: ${manifest.files.length} file(s)`);
  for (const file of manifest.files) console.log(`  ${file}`);
}

main();

