'use strict';

async function loadBuiltin(name) {
  if (typeof process.getBuiltinModule === 'function') {
    return process.getBuiltinModule(name);
  }
  if (typeof require === 'function') {
    return require(name);
  }
  const mod = await import('node:' + name);
  return mod.default !== undefined ? mod.default : mod;
}

function collectFiles(fs, path, dir, base, out) {
  const entries = fs.readdirSync(dir, { withFileTypes: true });
  for (const entry of entries) {
    if (entry.name.startsWith('.')) continue;
    const abs = path.join(dir, entry.name);
    if (entry.isFile()) {
      out.push(path.relative(base, abs));
    } else if (entry.isDirectory()) {
      collectFiles(fs, path, abs, base, out);
    }
  }
}

async function main() {
  const fs = await loadBuiltin('fs');
  const path = await loadBuiltin('path');

  const workspace = path.dirname(path.resolve(process.argv[1]));
  const manifestName = 'backup-manifest.json';

  const files = [];
  collectFiles(fs, path, workspace, workspace, files);

  const manifestPath = path.join(workspace, manifestName);
  const selected = files
    .filter((file) => path.resolve(workspace, file) !== manifestPath)
    .sort();

  const manifest = { files: selected };
  fs.writeFileSync(manifestPath, JSON.stringify(manifest, null, 2) + '\n');

  console.log('wrote ' + manifestName + ' with ' + selected.length + ' file(s)');
  for (const file of selected) {
    console.log('  ' + file);
  }
}

main();

